const input = {
    date: $input.first().json.date,
    weekday: $input.first().json.weekday,
    working_hours: $input.first().json.working_hours
};

// Convert date to Luxon DateTime object
const dateTime = DateTime.fromISO(input.date);
const hour = dateTime.hour;
const minute = dateTime.minute;

// Get the working hours for the provided weekday
const workHours = input.working_hours[input.weekday] || [];
// Function to check if the time is within a range
const available = workHours.some(range => {
    const [start, end] = range.split("-").map(time => {
        const [h, m] = time.split(":").map(Number);
        return { hour: h, minute: m };
    });
    return (
        (hour > start.hour || (hour === start.hour && minute >= start.minute)) &&
        (hour < end.hour || (hour === end.hour && minute <= end.minute))
    );
});

// Return result
return [{ available }];

// Helper function to convert time strings into Date objects
function parseTime(baseDate, timeStr) {
    const [hours, minutes] = timeStr.split(":").map(Number);
    const date = DateTime.fromISO(baseDate).set({ hour: hours, minute: minutes, second: 0, millisecond: 0 });
    return date;
}

// Check if a slot overlaps with a scheduled meeting
function isSlotBusy(slot, meetings) {
    return meetings.some(meeting => {
        const meetingStart = DateTime.fromISO(meeting.json.start);
        const meetingEnd = DateTime.fromISO(meeting.json.end);
        return (slot.start < meetingEnd && slot.end > meetingStart);
    });
}

// Check if the service duration can fit without overlapping busy slots
function canFitServiceDuration(slot, serviceDuration, endOfDay, meetings) {
    let serviceEnd = slot.start.plus({ minutes: serviceDuration });

    // Check if service exceeds working hours
    if (serviceEnd > endOfDay) return false;

    // Check if any overlapping meetings during the service duration
    return !meetings.some(meeting => {
        const meetingStart = DateTime.fromISO(meeting.json.start);
        const meetingEnd = DateTime.fromISO(meeting.json.end);
        return (slot.start < meetingEnd && serviceEnd > meetingStart);
    });
}

// Generate slots based on working hours
function generateSlots(baseDate, workingHours, meetings, serviceDuration) {
    let slots = [];
    const now = DateTime.now(); // Get current timestamp

    workingHours.forEach(period => {
        let startTime = parseTime(baseDate, period.split("-")[0]);
        let endTime = parseTime(baseDate, period.split("-")[1]);

        while (startTime < endTime) {
            let slotEnd = startTime.plus({ minutes: 30 });

            if (startTime > now && slotEnd <= endTime) { // Ensure slot start is in the future
                let status = "available";

                if (isSlotBusy({ start: startTime, end: slotEnd }, meetings) ||
                    !canFitServiceDuration({ start: startTime, end: slotEnd }, serviceDuration, endTime, meetings)) {
                    status = "busy";
                }

                slots.push({
                    start: startTime.toISO(),
                    end: slotEnd.toISO(),
                    status: status
                });
            }

            startTime = slotEnd;
        }
    });

    return slots;
}

// Main function execution
const baseDate = DateTime.fromISO($('Get Slots Trigger').first().json.query.date);
const workingHours = $('Get item from DB1').first().json.working_hours[$('Get Slots Trigger').first().json.query.weekday];
const scheduledMeetings = $input.all();
const serviceDuration = $('Get Slots Trigger').first().json.query.slot_duration;

// Generate slots
const slots = generateSlots(baseDate, workingHours, scheduledMeetings, serviceDuration);

return slots;

